# GPT-1 复现框架 Makefile (GPT-1 Reproduction Framework Makefile)
# 提供常用的开发和实验任务 (Provides common development and experiment tasks)

.PHONY: help install install-dev clean test lint format setup-data run-basic run-ablation docs

# 默认目标 (Default target)
help:
	@echo "GPT-1 复现框架 - 可用命令 (GPT-1 Reproduction Framework - Available Commands):"
	@echo ""
	@echo "安装和设置 (Installation and Setup):"
	@echo "  install          安装项目依赖 (Install project dependencies)"
	@echo "  install-dev      安装开发依赖 (Install development dependencies)"
	@echo "  setup-data       设置数据目录结构 (Setup data directory structure)"
	@echo ""
	@echo "开发工具 (Development Tools):"
	@echo "  clean            清理临时文件 (Clean temporary files)"
	@echo "  test             运行测试 (Run tests)"
	@echo "  lint             运行代码检查 (Run code linting)"
	@echo "  format           格式化代码 (Format code)"
	@echo ""
	@echo "实验运行 (Experiment Execution):"
	@echo "  run-basic        运行基础GPT-1实验 (Run basic GPT-1 experiment)"
	@echo "  run-ablation     运行消融实验 (Run ablation study)"
	@echo "  run-architecture 运行架构对比实验 (Run architecture comparison)"
	@echo "  create-config    创建示例配置 (Create sample configuration)"
	@echo ""
	@echo "文档和可视化 (Documentation and Visualization):"
	@echo "  docs             生成文档 (Generate documentation)"
	@echo "  visualize        生成实验可视化报告 (Generate experiment visualization reports)"

# 安装依赖 (Install dependencies)
install:
	pip install -r requirements.txt
	pip install -e .

install-dev:
	pip install -r requirements.txt
	pip install -e ".[dev,viz,all]"

# 设置数据目录 (Setup data directories)
setup-data:
	mkdir -p data/books_corpus
	mkdir -p data/snli
	mkdir -p data/multinli
	mkdir -p data/race
	mkdir -p data/sst2
	mkdir -p data/cola
	mkdir -p data/mrpc
	mkdir -p data/sts_b
	mkdir -p data/qnli
	mkdir -p data/scitail
	mkdir -p experiments
	mkdir -p logs
	mkdir -p checkpoints
	mkdir -p results
	@echo "✅ 数据目录结构已创建 (Data directory structure created)"
	@echo "请将对应的数据集放置到相应目录中 (Please place corresponding datasets in respective directories)"

# 清理临时文件 (Clean temporary files)
clean:
	find . -type f -name "*.pyc" -delete
	find . -type d -name "__pycache__" -delete
	find . -type d -name ".pytest_cache" -delete
	find . -type f -name ".coverage" -delete
	find . -type d -name "*.egg-info" -exec rm -rf {} +
	rm -rf build/
	rm -rf dist/

# 运行测试 (Run tests)
test:
	python -m pytest tests/ -v --cov=src --cov-report=html --cov-report=term

# 代码检查 (Code linting)
lint:
	flake8 src/ --max-line-length=120 --ignore=E203,W503
	mypy src/ --ignore-missing-imports

# 代码格式化 (Code formatting)
format:
	black src/ examples/ tests/ --line-length=120
	isort src/ examples/ tests/ --profile black

# 运行基础实验 (Run basic experiment)
run-basic:
	python src/main.py --config configs/base/gpt1_base.yaml --mode single

# 运行消融实验 (Run ablation study)
run-ablation:
	python src/main.py --config configs/ablation/complete_gpt1_ablation.yaml --mode ablation

# 运行架构对比实验 (Run architecture comparison)
run-architecture:
	python src/main.py --config configs/ablation/architecture_comparison.yaml --mode ablation

# 创建示例配置 (Create sample configuration)
create-config:
	python examples/run_experiments.py --mode config

# 快速测试 (Quick test)
test-quick:
	python examples/run_experiments.py --mode basic --quick

# 生成文档 (Generate documentation)
docs:
	@echo "生成项目文档 (Generating project documentation)..."
	@echo "请确保安装了文档依赖: pip install sphinx sphinx-rtd-theme"
	@echo "然后运行: sphinx-build -b html docs/ docs/_build/"

# 生成实验可视化 (Generate experiment visualizations)
visualize:
	@echo "生成实验可视化报告 (Generating experiment visualization reports)..."
	python -c "from src.utils.visualization_utils import create_experiment_report; \
	           import os; \
	           exp_dirs = [d for d in os.listdir('experiments') if os.path.isdir(os.path.join('experiments', d))]; \
	           [create_experiment_report(os.path.join('experiments', d)) for d in exp_dirs if exp_dirs]"

# 检查环境 (Check environment)
check-env:
	@echo "检查Python环境 (Checking Python environment):"
	@python --version
	@echo "检查CUDA可用性 (Checking CUDA availability):"
	@python -c "import torch; print(f'CUDA available: {torch.cuda.is_available()}')"
	@echo "检查GPU数量 (Checking number of GPUs):"
	@python -c "import torch; print(f'Number of GPUs: {torch.cuda.device_count()}')"

# 下载示例数据 (Download sample data)
download-sample-data:
	@echo "下载示例数据 (Downloading sample data)..."
	@echo "注意：实际使用时需要手动下载完整数据集 (Note: Full datasets need to be downloaded manually for actual use)"
	@echo "SNLI: https://nlp.stanford.edu/projects/snli/"
	@echo "RACE: http://www.cs.cmu.edu/~glai1/data/race/"
	@echo "SST-2: https://huggingface.co/datasets/sst2"
	@echo "CoLA: https://huggingface.co/datasets/cola"

# 监控GPU使用情况 (Monitor GPU usage)
monitor-gpu:
	watch -n 1 nvidia-smi

# 启动TensorBoard (Start TensorBoard)
tensorboard:
	tensorboard --logdir=experiments --port=6006 --host=0.0.0.0

# 性能基准测试 (Performance benchmarking)
benchmark:
	python -c "from src.utils.benchmark import run_benchmark; run_benchmark()"

# 验证安装 (Verify installation)
verify:
	@echo "验证安装 (Verifying installation)..."
	python -c "import src; print('✅ Package import successful')"
	python -c "from src.models.factory import ModelFactory; print('✅ Model factory working')"
	python -c "from src.data.factory import DataFactory; print('✅ Data factory working')"
	python -c "from src.training.factory import TrainerFactory; print('✅ Trainer factory working')"
	python -c "from src.evaluation.factory import EvaluatorFactory; print('✅ Evaluator factory working')"
	@echo "✅ 所有组件验证成功 (All components verified successfully)"

# 运行完整的CI流程 (Run complete CI pipeline)
ci: clean lint test verify
	@echo "✅ CI流程完成 (CI pipeline completed)"

# 准备发布 (Prepare release)
release: clean format lint test docs
	python setup.py sdist bdist_wheel
	@echo "✅ 发布包已准备就绪 (Release package ready)"

# 显示项目统计信息 (Show project statistics)
stats:
	@echo "项目统计信息 (Project Statistics):"
	@echo "代码行数 (Lines of code):"
	@find src/ -name "*.py" -exec wc -l {} + | tail -1
	@echo "测试覆盖率 (Test coverage):"
	@python -m pytest tests/ --cov=src --cov-report=term-missing | grep TOTAL
	@echo "配置文件数量 (Number of config files):"
	@find configs/ -name "*.yaml" | wc -l
